WITH ranked AS (SELECT id, session_id, event_type, page FROM web_events QUALIFY RANK() OVER (PARTITION BY page ORDER BY event_time) = 1), cleaned AS (SELECT *, LOWER(event_type) AS event_type_lower FROM ranked WHERE page IS NOT NULL), base AS (SELECT *, LENGTH(event_type) AS event_type_length, COALESCE(page, 'OTHER') AS page_filled FROM cleaned WHERE event_type = 'page_view'), cleaned_web_events AS (SELECT id, session_id, event_type, page, event_type_lower, event_type_length, CONCAT_WS('-', event_type, page) AS event_type_page_key FROM base WHERE page IS NOT NULL AND page IS DISTINCT FROM '/search'), joined AS (SELECT s.id, s.session_id, s.event_type, s.page, s.event_type_lower, s.event_type_length, d.device, d.country FROM cleaned_web_events s LEFT JOIN sessions d ON s.session_id = d.id), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY page ORDER BY event_type_length DESC NULLS FIRST, id) AS rank_in_group FROM joined QUALIFY rank_in_group = 1), joined_web_events AS (SELECT src.*, s.device AS session_device, s.country AS session_country FROM deduped src JOIN sessions s ON src.session_id = s.id) SELECT id, page, event_type_lower, event_type_length, country, rank_in_group, session_device FROM joined_web_events ORDER BY id DESC NULLS LAST;
